4 myret_t r; // (cid:5893)(cid:9534)(cid:6705)(cid:1)(cid:10689)(cid:1882)(cid:10729)(cid:1861)(cid:15)(cid:7125)(cid:3149)(cid:3797)(cid:1)(cid:6569)(cid:1)(cid:2173)(cid:1861)(cid:2) 5 r.x = 1; 6 r.y = 2; 7 return (void *) &r; 8 } 이 코드에서 mythread의 스택에 변수 r이 할당되어 있다. 이 값은 쓰레드가 리턴할 때 자동적으로 해제된다(어쨌건, 이게 스택이 사용하기 쉬운 이유이다). 현재 해제된 변수를 가리키는 포인터를 반환하는 것은 온갖 종류의 좋지 않은 결과를 가져온다. 분명 반환받았다고 생각하는 값을 출력해 보면 (꼭 그런 건 아니지만) 놀라게 될 것이다. 직접 결과를 확인해 보라2. 마지막으로,pthread_create()를 사용하여 쓰레드를 생성하고 직후에pthread_join() 을 호출한다는 것은 쓰레드를 생성하는 아주 이상한 방법이다. 사실 작(cid:6694)을 똑같이 할 2)다행스럽게 당신이 이러한 코드를 작성하면gcc컴파일러가 투덜댈 것이다.컴파일러의 경고 메시지를 잘 읽어봐야 하는 또 다른 이유가 되겠다. 4 운영체제: 아주 쉬운 세 가지 이야기 [V.0.90]

